  stages:[
   stage('Увидеть направленное продвижение','В общей истории отмечен участок от закрытия 101 на свече 25 до 118 на свече 37. Цена продвинулась заметно дальше обычных соседних колебаний.','Сравни выделенный отрезок с более ранними короткими волнами.',64),
   stage('Найти обратный ход','После вершины у свечи 37 цена возвращается к 111 у свечи 48. Это обратное движение относительно предыдущего роста. Пока слово «откат» только описывает связь двух движений.','Найди начало и конец обратного хода. Не делай из названия обещание нового роста.',64),
   stage('Выделить область паузы','После возврата на свечах 50–64 цена несколько раз колеблется около 111–114. По этому позднему окну выделена полоса 110,7–114,6. Последнее закрытие 112,2 остаётся внутри.','Сравни повторные подходы в выделенном позднем окне. Предыдущий обратный ход отмечен отдельно.',64),
   stage('Отличить сохранение паузы от выхода','Одна ветка остаётся вблизи прежнего диапазона; другая закрывается ниже 110,7 и продолжает снижение. Название прежнего движения не выбирало этот исход заранее.','Сохрани границы диапазона и покажи, в какой ветке появляется новое событие.',76)
  ],
  teaching:{goal:'Различать импульс, обратный ход и паузу на достаточно длинной истории цены.',plain:'Импульс описывает заметное направленное продвижение. Откат — обратный ход относительно него. Диапазон — колебания между выбранными границами без устойчивого продвижения.',read:'Сначала выделяется движение 25–37, затем обратный ход 37–48 и, наконец, поздний диапазон. Общая история остаётся на месте, меняется разметка нужного участка.',example:'Повышение 101→118 сменяется возвратом к 111. Позже цена колеблется около 111–114. До продолжения последнее закрытие 112,2 находится в полосе 110,7–114,6. Сохранение паузы и выход ниже неё — разные наблюдаемые продолжения.',terms:[{term:'Импульс',meaning:'Направленное продвижение на выбранном масштабе.'},{term:'Пауза',meaning:'Поздние колебания без дальнейшего устойчивого продвижения.'}],takeaway:'Название движения описывает прошлое; продолжение проверяют новыми событиями.'},
  practice:{...question('В новом участке сначала было снижение, затем возврат и поздние колебания 207–210. Что доказывает слово «откат»?','Только обратное движение относительно предыдущего участка; дальнейшее направление ещё неизвестно.','Обязательное возвращение к прежнему снижению.','Сравниваются движения одного масштаба; слово не содержит будущих цен.'),reveal:'Сравни сохранение диапазона с выходом из него, сохранив первоначальные границы.'},
  quiz:[question('Что нужно для наблюдения выхода из диапазона?','Новое событие за заранее выбранной границей.','Достаточно назвать предыдущее движение импульсом.','Название и наблюдаемый выход относятся к разным данным.')],
  examples:[{id:'base',title:'Поздняя пауза сохраняется',step:3,alternate:false,body:'Новые свечи продолжают колебания рядом с той же полосой. Убедись, что границы не переносятся под каждую свечу.',task:'Сравни поздние закрытия с 110,7–114,6.'},{id:'contrast',title:'Выход ниже области паузы',step:3,alternate:true,body:'Первое новое закрытие 110,3 находится ниже 110,7. Это наблюдаемый выход, который не был гарантирован словом «откат».',task:'Найди первое закрытие за нижней границей.'},{id:'checkpoint',title:'Различаем участки до исхода',step:2,stop:64,body:'Известны импульс, обратный ход и поздний диапазон. Продолжение нового подхода ещё скрыто.',task:'Назови три участка и условие появления нового события.'}],
  annotate:({bars,step,practice})=>{const start=practice?25:24,top=practice?39:36,end=practice?46:47,rangeFrom=practice?51:49,lo=practice?206.5:110.7,hi=practice?210.2:114.6;return{markers:marks(mark(bars,start,'c','Начало направленного участка'),mark(bars,top,practice?'l':'h','Конец импульса',practice?'arrowUp':'arrowDown'),step>=1&&mark(bars,end,'c','Обратный ход'),step>=2&&mark(bars,63,'c','Поздняя пауза')),zones:step>=2?[zone(lo,hi,'Поздний диапазон паузы',rangeFrom,bars.length-1)]:[],segments:[segment(bars,start,'c',top,'c','Импульс'),step>=1&&segment(bars,top,'c',end,'c','Обратный ход')].filter(Boolean),highlight:step===0?[start,top]:step===1?[top,end]:[51,55,59,63],focus:step===0?top:step===1?end:63};}
