  examples:[{id:'base',title:'Нижняя граница пройдена закрытием',step:3,alternate:false,body:'После одинаковой истории новое закрытие 103,9 оказывается ниже 104,5. Теперь появилось именно то событие, которого не было на свече 80.',task:'Найди первое закрытие ниже нижней полосы.'},{id:'contrast',title:'Возврат вверх вместо выхода вниз',step:3,alternate:true,body:'Цена возвращается к верхним ценам; закрытие 114,8 позже находится выше 114,5. Исходная форма не исключала эту ветку.',task:'Сравни новые цены с заранее выбранным верхним условием отмены.'},{id:'checkpoint',title:'Две вершины без подтверждённого выхода',step:2,stop:80,body:'Видно 80 свечей. Последнее закрытие 106,2 ещё у нижней области, а закрытия ниже 104,5 нет.',task:'Отдели уже видимую форму от ещё отсутствующего события.'}],
